// PayPal Orders v2 client — a genuine second payment rail alongside Stripe.
//
// GATING. Exactly the pattern `lib/seo/searchConsole.ts`'s `gscConfigured()` uses:
// a pure `paypalConfigured()` reading only env vars, checked BEFORE every server
// action and BEFORE the client ever renders a PayPal button. `PAYPAL_CLIENT_ID`,
// `PAYPAL_CLIENT_SECRET` and `PAYPAL_WEBHOOK_ID` do not exist in any environment yet
// (the owner is creating a PayPal Business account in parallel) — every function
// here is inert (returns null / throws a caught, typed error) rather than crashing
// when they are absent, so this ships dark and lights up the moment the three env
// vars are set. No fake/sandbox fallback credentials are baked in anywhere.
//
// MONEY MODEL. PayPal is authorized then CAPTURED server-to-server — the same
// "never trust the client" posture Stripe gets for free from `checkout.sessions`.
// `createPayPalOrder` is called from OUR server action with a price WE computed;
// `capturePayPalOrder` is a server-to-server call PayPal itself answers, and only
// its answer (not anything the browser reports) is treated as "the money moved".
// See lib/actions-payment-providers.ts for how this plugs into the same
// reserve → pay → fulfil pipeline every other payment method uses.
//
// FULFILMENT SEAM. This file never touches provisioning, the database beyond a
// `PendingExternalPayment` row, or Stripe. It hands a captured order id + amount
// back to the caller, which routes it through `fulfilExternalPayment`
// (lib/fulfil-checkout.ts) — the SAME dispatch `fulfilCheckoutSession` uses for
// Stripe. See that file for the unification.

const SANDBOX_BASE = "https://api-m.sandbox.paypal.com";
const LIVE_BASE = "https://api-m.paypal.com";

function clientId(): string {
  return (process.env.PAYPAL_CLIENT_ID ?? "").trim();
}
function clientSecret(): string {
  return (process.env.PAYPAL_CLIENT_SECRET ?? "").trim();
}

/** Is PayPal configured in this environment? Gates every UI surface and action. */
export function paypalConfigured(): boolean {
  return !!clientId() && !!clientSecret();
}

/**
 * Which PayPal environment to call. Defaults to sandbox — a missing/blank
 * `PAYPAL_MODE` must never accidentally take real money, so "live" is opt-in only.
 */
function apiBase(): string {
  return (process.env.PAYPAL_MODE ?? "").trim().toLowerCase() === "live" ? LIVE_BASE : SANDBOX_BASE;
}

/** The publishable-safe client id, for the browser SDK script. "" when unconfigured. */
export function paypalClientIdPublic(): string {
  return clientId();
}

type TokenCache = { token: string; expiresAt: number } | null;
let tokenCache: TokenCache = null;

async function getAccessToken(): Promise<string> {
  if (!paypalConfigured()) throw new Error("PayPal is not configured");
  const now = Date.now();
  if (tokenCache && tokenCache.expiresAt - 30_000 > now) return tokenCache.token;

  const basic = Buffer.from(`${clientId()}:${clientSecret()}`).toString("base64");
  const res = await fetch(`${apiBase()}/v1/oauth2/token`, {
    method: "POST",
    headers: {
      Authorization: `Basic ${basic}`,
      "Content-Type": "application/x-www-form-urlencoded",
    },
    body: "grant_type=client_credentials",
  });
  if (!res.ok) {
    throw new Error(`PayPal OAuth failed: ${res.status} ${await res.text().catch(() => "")}`);
  }
  const json = (await res.json()) as { access_token: string; expires_in: number };
  tokenCache = { token: json.access_token, expiresAt: now + json.expires_in * 1000 };
  return json.access_token;
}

async function paypalFetch<T>(path: string, init: RequestInit & { idempotencyKey?: string } = {}): Promise<T> {
  const token = await getAccessToken();
  const headers: Record<string, string> = {
    Authorization: `Bearer ${token}`,
    "Content-Type": "application/json",
    ...(init.headers as Record<string, string> | undefined),
  };
  if (init.idempotencyKey) headers["PayPal-Request-Id"] = init.idempotencyKey;
  const res = await fetch(`${apiBase()}${path}`, { ...init, headers });
  const text = await res.text();
  let json: unknown = null;
  try {
    json = text ? JSON.parse(text) : null;
  } catch {
    /* non-JSON error body — fall through with json === null */
  }
  if (!res.ok) {
    const detail = json && typeof json === "object" ? JSON.stringify(json) : text;
    throw new Error(`PayPal API ${path} failed: ${res.status} ${detail}`.slice(0, 1000));
  }
  return json as T;
}

export type PayPalOrder = {
  id: string;
  status: string;
  purchase_units?: Array<{ custom_id?: string; amount?: { currency_code: string; value: string } }>;
};

/**
 * Create a PayPal order for `amountCents` (a REAL server-computed price, never a
 * client-supplied number). `pendingId` is the id of the `PendingExternalPayment`
 * row this order is for — it rides as `custom_id`, PayPal's one small
 * (127-char) free-form field, so the full order metadata never needs to reach
 * PayPal at all; PayPal is only ever asked to move money and echo the id back.
 */
export async function createPayPalOrder(opts: {
  amountCents: number;
  currency?: string;
  pendingId: string;
  description: string;
}): Promise<PayPalOrder> {
  if (!(opts.amountCents > 0)) throw new Error("PayPal order amount must be positive");
  const value = (opts.amountCents / 100).toFixed(2);
  return paypalFetch<PayPalOrder>("/v2/checkout/orders", {
    method: "POST",
    idempotencyKey: `nxeon_pp_create_${opts.pendingId}`,
    body: JSON.stringify({
      intent: "CAPTURE",
      purchase_units: [
        {
          custom_id: opts.pendingId,
          description: opts.description.slice(0, 127),
          amount: { currency_code: (opts.currency ?? "USD").toUpperCase(), value },
        },
      ],
    }),
  });
}

/**
 * Capture a PayPal order server-to-server. This — not anything the browser's
 * `onApprove` callback reports — is the authoritative "did the money move"
 * answer. Idempotent: PayPal returns the existing capture on a repeated call for
 * an order already captured (COMPLETED), so the client-driven capture and the
 * webhook backstop can race safely, exactly like the Stripe confirm/webhook race.
 */
export async function capturePayPalOrder(orderId: string): Promise<PayPalOrder & {
  purchase_units?: Array<{
    custom_id?: string;
    payments?: { captures?: Array<{ id: string; status: string; amount?: { currency_code: string; value: string } }> };
  }>;
}> {
  return paypalFetch(`/v2/checkout/orders/${encodeURIComponent(orderId)}/capture`, {
    method: "POST",
    idempotencyKey: `nxeon_pp_capture_${orderId}`,
  });
}

/** Read back an order (used by the webhook, which only gets an id in the event). */
export async function getPayPalOrder(orderId: string): Promise<PayPalOrder> {
  return paypalFetch(`/v2/checkout/orders/${encodeURIComponent(orderId)}`, { method: "GET" });
}

/**
 * Verify a webhook really came from PayPal using PayPal's own server-to-server
 * verification endpoint (the documented method — no local certificate-chain
 * validation to get subtly wrong). Requires `PAYPAL_WEBHOOK_ID` (the id of the
 * webhook configured in the PayPal dashboard for this app). Returns false (never
 * throws) on any failure to verify or on missing configuration — a webhook that
 * cannot be PROVEN authentic must be rejected, not treated as authentic-by-default.
 */
export async function verifyPayPalWebhookSignature(
  headers: Headers,
  rawBody: string,
): Promise<boolean> {
  const webhookId = (process.env.PAYPAL_WEBHOOK_ID ?? "").trim();
  if (!paypalConfigured() || !webhookId) return false;
  let event: unknown;
  try {
    event = JSON.parse(rawBody);
  } catch {
    return false;
  }
  try {
    const result = await paypalFetch<{ verification_status: string }>("/v1/notifications/verify-webhook-signature", {
      method: "POST",
      body: JSON.stringify({
        auth_algo: headers.get("paypal-auth-algo"),
        cert_url: headers.get("paypal-cert-url"),
        transmission_id: headers.get("paypal-transmission-id"),
        transmission_sig: headers.get("paypal-transmission-sig"),
        transmission_time: headers.get("paypal-transmission-time"),
        webhook_id: webhookId,
        webhook_event: event,
      }),
    });
    return result.verification_status === "SUCCESS";
  } catch {
    return false;
  }
}

// Coinbase Commerce client — the crypto payment rail (BTC/ETH/USDC/etc, settled
// as a USD-denominated charge). Same gating discipline as lib/paypal.ts: a pure
// `coinbaseConfigured()` over env vars, inert everywhere `COINBASE_COMMERCE_API_KEY`
// / `COINBASE_COMMERCE_WEBHOOK_SECRET` are unset (neither exists yet in any
// environment — the owner has not set up Coinbase Commerce yet either).
//
// UX NOTE (deliberate, and worth flagging rather than silently deviating from the
// mockup): Coinbase Commerce has no inline/embeddable Elements-style widget the way
// Stripe does. The real integration is: create a charge server-side, send the
// customer to Coinbase's OWN hosted charge page (`hosted_url`) to pick a coin and
// see the deposit address/QR code, and learn the outcome via webhook
// (`charge:confirmed` / `charge:failed` / `charge:delayed`). So "Cryptocurrency" in
// our radio list opens a new tab to Coinbase rather than rendering address fields
// inline — presented honestly in the UI copy, not as a fake inline flow.
//
// Also deliberately NOT copying the mockup's "Instant" badge for crypto: on-chain
// confirmation takes minutes, not "instant" in the sense every other badge on this
// page means it (card/wallet auth is genuinely sub-second). Copy here says "Pay
// with crypto via Coinbase Commerce" with no speed claim, matching every other
// place on this site that got audited for exactly this kind of overclaim (see
// PaymentTrustBar.tsx's HONESTY comment on invented claims).

const API_BASE = "https://api.commerce.coinbase.com";
const API_VERSION = "2018-03-22"; // Coinbase Commerce's pinned API version header

function apiKey(): string {
  return (process.env.COINBASE_COMMERCE_API_KEY ?? "").trim();
}

/** Is Coinbase Commerce configured in this environment? Gates every UI surface. */
export function coinbaseConfigured(): boolean {
  return !!apiKey();
}

export type CoinbaseCharge = {
  id: string;
  code: string;
  hosted_url: string;
  timeline?: Array<{ status: string; time: string }>;
  metadata?: Record<string, string>;
};

async function coinbaseFetch<T>(path: string, init: RequestInit = {}): Promise<T> {
  if (!coinbaseConfigured()) throw new Error("Coinbase Commerce is not configured");
  const res = await fetch(`${API_BASE}${path}`, {
    ...init,
    headers: {
      "X-CC-Api-Key": apiKey(),
      "X-CC-Version": API_VERSION,
      "Content-Type": "application/json",
      ...(init.headers as Record<string, string> | undefined),
    },
  });
  const text = await res.text();
  let json: unknown = null;
  try {
    json = text ? JSON.parse(text) : null;
  } catch {
    /* non-JSON error body */
  }
  if (!res.ok) {
    const detail = json && typeof json === "object" ? JSON.stringify(json) : text;
    throw new Error(`Coinbase Commerce API ${path} failed: ${res.status} ${detail}`.slice(0, 1000));
  }
  return ((json as { data?: T })?.data ?? json) as T;
}

/**
 * Create a charge for `amountCents` (a REAL server-computed price). `pendingId`
 * (the `PendingExternalPayment` row id) rides in `metadata.nxeonPendingId` — unlike
 * PayPal's 127-char `custom_id`, Coinbase's charge metadata has no such limit, but
 * we still only ever put the small pointer here, never the full order payload, so
 * the single source of truth for what was ordered stays our own database row.
 */
export async function createCoinbaseCharge(opts: {
  amountCents: number;
  currency?: string;
  pendingId: string;
  name: string;
  description: string;
  redirectUrl: string;
  cancelUrl: string;
}): Promise<CoinbaseCharge> {
  if (!(opts.amountCents > 0)) throw new Error("Coinbase charge amount must be positive");
  return coinbaseFetch<CoinbaseCharge>("/charges", {
    method: "POST",
    body: JSON.stringify({
      name: opts.name,
      description: opts.description,
      pricing_type: "fixed_price",
      local_price: { amount: (opts.amountCents / 100).toFixed(2), currency: (opts.currency ?? "USD").toUpperCase() },
      metadata: { nxeonPendingId: opts.pendingId },
      redirect_url: opts.redirectUrl,
      cancel_url: opts.cancelUrl,
    }),
  });
}

/** Read back a charge (used by the webhook handler for a defence-in-depth re-check). */
export async function getCoinbaseCharge(codeOrId: string): Promise<CoinbaseCharge> {
  return coinbaseFetch<CoinbaseCharge>(`/charges/${encodeURIComponent(codeOrId)}`, { method: "GET" });
}

/**
 * Verify a webhook really came from Coinbase Commerce: HMAC-SHA256 of the RAW
 * request body, keyed by the shared webhook secret, compared to the
 * `X-CC-Webhook-Signature` header — Coinbase Commerce's documented method. A
 * timing-safe comparison and a length check first (crypto.timingSafeEqual throws
 * on mismatched lengths rather than returning false, so a naive call would leak
 * timing information on the FIRST forged attempt with a wrong-length signature).
 * Returns false (never throws) on any missing configuration or malformed header —
 * an unverifiable webhook must be rejected, not treated as authentic-by-default.
 */
export async function verifyCoinbaseWebhookSignature(rawBody: string, signatureHeader: string | null): Promise<boolean> {
  const secret = (process.env.COINBASE_COMMERCE_WEBHOOK_SECRET ?? "").trim();
  if (!secret || !signatureHeader) return false;
  const { createHmac, timingSafeEqual } = await import("node:crypto");
  const expected = createHmac("sha256", secret).update(rawBody, "utf8").digest("hex");
  const a = Buffer.from(expected, "hex");
  const b = Buffer.from(signatureHeader.trim(), "hex");
  if (a.length !== b.length || a.length === 0) return false;
  return timingSafeEqual(a, b);
}

