model FulfilledSession {
  id              String   @id @default(cuid())
  stripeSessionId String   @unique
  kind            String // "order" | "resize" | "diskExpand" | "topup"
  status          String   @default("CLAIMED") // CLAIMED | DONE | FAILED
  detail          String? // server id / job id, or the failure reason
  createdAt       DateTime @default(now())
  updatedAt       DateTime @updatedAt
}

// ---- PayPal / Coinbase Commerce bridge (2026-08-26 embedded-payment-ui build) ----
//
// WHY THIS EXISTS. Stripe Checkout sessions carry their own metadata (nxeonOrder,
// nxeonOrderPrice, nxeonPromoReservation, …) directly at Stripe, so
// `classifyCheckoutSession` can read it straight off the retrieved session. PayPal's
// `custom_id` is a 127-character field — nowhere near enough for a packed order
// intent — and while Coinbase Commerce's charge metadata has no such limit, putting
// the one full order payload in TWO places (our DB and the provider) would leave a
# never TWO different views of "what was this purchase for" if they ever drifted.
// So instead: this row is the ONE place the full metadata blob lives (in the exact
// same nxeon* key shape Stripe's metadata already uses), and the provider is only
// ever given this row's id (PayPal's `custom_id`, Coinbase's `metadata.nxeonPendingId`)
// to hand back on webhook/capture. `lib/fulfil-checkout.ts`'s `fulfilExternalPayment`
// reconstructs a synthetic session-shaped object from this row's `metadata` field and
// feeds it through the EXACT SAME `classifyCheckoutSession` + dispatch pipeline Stripe
// uses — this table is a bridge to that pipeline, not a second one.
//
// `providerRef` + `provider` together are the idempotency key `FulfilledSession`
// dispatches on (passed through as a synthetic `stripeSessionId` of the form
// `"paypal:<orderId>"` / `"coinbase:<chargeCode>"`), so a client-driven capture and
// the provider's webhook racing each other is exactly as safe as the Stripe
// confirm-redirect/webhook race already is.
model PendingExternalPayment {
  id          String   @id @default(cuid())
  provider    String // "paypal" | "coinbase"
  kind        String // "order" | "gameOrder" | "hostOrder" | "emailOrder"
  userId      String
  amountCents Int
  currency    String   @default("usd")
  // Packed via the SAME `packMetadata` size guard lib/stripe.ts uses for Stripe
  // metadata — JSON, refused (not truncated) past the cap. Same nxeon* key shape.
  metadata    String
  providerRef String? // PayPal order id / Coinbase charge code, set once known
  status      String   @default("PENDING") // PENDING | PAID | FAILED | EXPIRED
  createdAt   DateTime @default(now())
  updatedAt   DateTime @updatedAt

  @@index([provider, providerRef])
  @@index([userId])
}

