/* ------------------------------------------------------------------ *
 * Custom Checkout (ui_mode: "elements") — the embedded-payment-UI build
 * ------------------------------------------------------------------ *
 *
 * Every `create*Checkout` function above opens a Checkout Session with
 * `ui_mode: "embedded_page"` — Stripe's own prebuilt payment UI, mounted as-is
 * inside `StripeCheckoutModal`. The four functions below open the SAME KIND of
 * Checkout Session — same `mode: "payment"`, same `customer` +
 * `payment_intent_data.setup_future_usage`, same nxeon* metadata keys, same
 * `return_url` — but with `ui_mode: "elements"` instead: Stripe's "Custom
 * Checkout" mode, whose client secret is consumed client-side by
 * `stripe.initCheckout()` + `<PaymentElement>` / `<ExpressCheckoutElement>`
 * (components/customer/PaymentStep.tsx), so the Review step can render its OWN
 * payment-method list (Card / Google Pay / Apple Pay inline via Stripe, PayPal
 * and Coinbase Commerce as separate non-Stripe rails alongside it) instead of
 * Stripe's own hosted/embedded page.
 *
 * WHY A CHECKOUT SESSION AT ALL, RATHER THAN A RAW PaymentIntent + individual
 * Elements. This is the single highest-leverage decision in the payment-UI
 * change, so it is written down here rather than only in a PR description. A raw
 * PaymentIntent (`stripe.paymentIntents.create` + `<CardNumberElement>` /
 * `<CardExpiryElement>` / `<CardCvcElement>`) would allow the card fields to be
 * laid out with even more precision — three literally separate boxes instead of
 * one Stripe-drawn group — but it would ALSO mean this card leg no longer
 * produces a Checkout Session at all: no `checkout.session.completed` webhook,
 * nothing for `classifyCheckoutSession` to read, and therefore a SECOND Stripe
 * fulfilment path (a `payment_intent.succeeded` webhook, a second classify
 * function, a second dispatch) sitting next to the audited one, purely to serve a
 * card-field layout preference. That directly contradicts this build's own
 * "fulfilment path unification" requirement, and it is exactly the class of
 * duplicated money-plumbing this file's incident history (see the block comments
 * on `packMetadata`, `retrieveCheckoutSession`, `isPurchaseLegSession`) keeps
 * finding real bugs in. Staying on Checkout Sessions makes the Stripe side of the
 * new UI a PURE PRESENTATION change: same webhook
 * (app/api/stripe/webhook/route.ts), same `classifyCheckoutSession`, same
 * `fulfilCheckoutSession`, same `test/checkout-metadata.test.ts` guarantees — none
 * of that code changes, or needs to change, for this feature. PayPal and Coinbase
 * Commerce, which have no Checkout Session equivalent, reach the SAME dispatch
 * through `fulfilExternalPayment` (lib/fulfil-checkout.ts) instead — see that
 * file for how a second and third rail plug into one fulfilment engine.
 *
 * `payment_method_types: ["card"]` is set explicitly (rather than leaving it to
 * the Dashboard's automatic-payment-methods list) so the Payment Element only
 * ever offers card / Apple Pay / Google Pay. Stripe also supports a "paypal"
 * payment-method type of its OWN; this build's PayPal integration is a genuine
 * separate rail (lib/paypal.ts, the real Orders API, its own fulfilment entry
 * point) and the two must never both appear as options in the same radio list.
 */
const CUSTOM_CHECKOUT_UI_MODE: Stripe.Checkout.SessionCreateParams["ui_mode"] = "elements";

/** Same shape as `EmbeddedCheckout`; named separately at call sites for clarity
 *  about which `ui_mode` produced it. Card data still never touches our server —
 *  Stripe's Payment Element owns the card fields inside this checkout, exactly as
 *  Embedded Checkout's iframe does. */
export type CustomCheckout = EmbeddedCheckout;

/** The card-leg analogue of `createOrderCheckout`, for the new embedded Payment
 *  step. Same pricing/refusal rules (see that function's doc comment); the only
 *  difference is `ui_mode`. */
export async function createOrderPaymentSession(
  user: CardUser,
  amountCents: number,
  intent: OrderIntent,
  sold?: OrderPrice | null,
  campaign?: string,
  promoReservationToken?: string | null,
  couponReservationToken?: string | null,
): Promise<CustomCheckout | null> {
  if (!stripeConfigured() || amountCents <= 0) return null;
  const base = process.env.APP_URL ?? "http://localhost:3000";
  const price = sold ?? orderPriceOf(await orderQuote(intent));
  const orderTotalCents = price.chargeCents + (price.taxCents ?? 0);
  if (orderTotalCents < amountCents) {
    throw new Error(`Order payment session: card leg ${amountCents}c exceeds the order total ${orderTotalCents}c`);
  }
  const slim: OrderIntent = { ...intent, sshPublicKey: undefined, sshKeyName: undefined };
  const { ensureStripeCustomer } = await import("./stripe-cards");
  const customerId = await ensureStripeCustomer(user);
  const session = await stripe().checkout.sessions.create(
    {
      mode: "payment",
      customer: customerId,
      payment_method_types: ["card"],
      payment_intent_data: { setup_future_usage: "off_session" },
      expires_at: Math.floor((Date.now() + ORDER_CHECKOUT_EXPIRES_MS) / 1000),
      line_items: [
        {
          price_data: { currency: "usd", product_data: { name: `Nxeon VPS — ${intent.hostname}` }, unit_amount: amountCents },
          quantity: 1,
        },
      ],
      metadata: {
        nxeonUserId: user.id,
        nxeonOrder: packMetadata("Order intent", slim),
        nxeonOrderPrice: packMetadata("Order price", price),
        nxeonPromoCampaign: sanitizeCampaign(campaign),
        ...(promoReservationToken ? { nxeonPromoReservation: promoReservationToken } : {}),
        ...(couponReservationToken ? { nxeonCouponReservation: couponReservationToken } : {}),
      },
      ui_mode: CUSTOM_CHECKOUT_UI_MODE,
      return_url: `${base}/api/stripe/confirm?session_id={CHECKOUT_SESSION_ID}`,
    },
    EMBEDDED_REQUEST_OPTS,
  );
  return session.client_secret ? { clientSecret: session.client_secret, publishableKey: stripePublishableKey() } : null;
}

