"use server";

// PayPal / Coinbase Commerce order-creation + capture actions for the embedded
// Payment step (components/customer/PaymentStep.tsx).
//
// WHAT THIS FILE IS. The card-leg twin of these functions already exists per
// product (payAndDeploy in lib/actions.ts, payAndDeployGame in
// lib/actions-gameplans.ts, placeHostingOrder in lib/actions-hosting.ts,
// orderEmailHosting in lib/actions-email-hosting.ts) — each computes a quote,
// applies the wallet split (and, for VPS/hosting, the first-month-free promo
// reservation dance), then opens a Stripe Checkout session for the remainder.
// The functions below mirror that SAME pricing path per product — reusing the
// exact same quote/reservation/charge-formula functions those files export,
// never a second copy of a price — but open a PayPal order or a Coinbase
// Commerce charge instead of a Stripe session for the card-leg amount.
//
// WHY NOT REFACTOR THE EXISTING ACTIONS TO SHARE ONE HELPER. `payAndDeploy` in
// particular is a long, heavily-audited function with several real-incident
// scars documented inline (the H2 re-pricing incident, the first-month-free
// money race, the coupon race). Extracting a shared "quote + reserve" helper
// out of it, under time pressure, for a brand-new payment rail that does not
# exist in production yet, is a worse risk than a bounded amount of duplication
// here. Every duplicated line is a direct, close mirror of its sibling and is
// commented as such, so a future reviewer can diff them side by side.
//
// FULFILMENT. Every creation function below writes ONE PendingExternalPayment
// row (the full nxeon*-shaped metadata, packed via packExternalPaymentMetadata —
// the SAME 500-char-per-value refuse-don't-truncate guard Stripe metadata uses)
// and hands the provider only that row's id. `captureExternalPayPalOrder` (client-
// driven, called from onApprove) and the PayPal/Coinbase webhooks
// (app/api/webhooks/{paypal,coinbase}/route.ts) both call
// `fulfilExternalPayment` (lib/fulfil-checkout.ts), which reconstructs a
// synthetic Stripe-session-shaped object from that row and runs it through the
// EXACT SAME dispatch `fulfilCheckoutSession` uses for Stripe — one fulfilment
// engine, three rails.
//
// SCOPE. Resize and disk-expand upgrades are NOT wired to PayPal/Coinbase here
// (nor to the new embedded Stripe UI) — see the payment-UI build's report for
// why. Every function below is for the four DEPLOY kinds only: order (VPS),
// gameOrder, hostOrder, emailOrder.

import { cookies, headers } from "next/headers";
