import { coinbaseConfigured, createCoinbaseCharge } from "./coinbase-commerce";
import { fulfilExternalPayment, packExternalPaymentMetadata, type FulfilResult } from "./fulfil-checkout";

/** Same window Stripe's card-leg checkout uses for its "abandoned checkout" grace
 *  (lib/actions.ts's RESERVATION_GRACE_MS, duplicated here rather than exported
 *  out of that file purely to avoid touching it for a constant). PayPal orders and
 *  Coinbase charges each have their own, LONGER provider-side expiry (PayPal ~3h,
 *  Coinbase Commerce ~1h), so a hold reserved for this long always outlives the
 *  window the customer could actually still be paying in. An abandoned hold is
 *  never stuck forever regardless: `sweepExpiredReservations` (worker/index.ts)
 *  is the same backstop the Stripe path already relies on. */
const RESERVATION_GRACE_MS = 10 * 60 * 1000;
const PAYPAL_HOLD_MS = 3 * 60 * 60 * 1000 + RESERVATION_GRACE_MS;
const COINBASE_HOLD_MS = 60 * 60 * 1000 + RESERVATION_GRACE_MS;

function appBase(): string {
  return process.env.APP_URL ?? "http://localhost:3000";
}

export type ExternalCheckoutStatus = {
  paypalReady: boolean;
  coinbaseReady: boolean;
  paypalClientId: string;
};

/** Pure env-var read, safe to call from a server component and pass down as a
 *  plain prop — exactly the `xConfigured()` gating pattern `gscConfigured()` uses. */
export function externalCheckoutStatus(): ExternalCheckoutStatus {
  return {
    paypalReady: paypalConfigured(),
    coinbaseReady: coinbaseConfigured(),
    paypalClientId: paypalClientIdPublic(),
  };
}

type CreateResult =
  | { error: string }
  | { paypalOrderId: string; pendingId: string }
  | { hostedUrl: string; pendingId: string };

async function openPayPal(opts: {
  userId: string;
  kind: string;
  amountCents: number;
  metadata: Record<string, string>;
  description: string;
}): Promise<{ error: string } | { paypalOrderId: string; pendingId: string }> {
  if (!paypalConfigured()) return { error: "PayPal isn't set up yet — try another payment method." };
  const row = await db.pendingExternalPayment.create({
    data: {
      provider: "paypal",
      kind: opts.kind,
      userId: opts.userId,
      amountCents: opts.amountCents,
      currency: "usd",
      metadata: JSON.stringify(opts.metadata),
    },
  });
  try {
    const order = await createPayPalOrder({ amountCents: opts.amountCents, pendingId: row.id, description: opts.description });
    await db.pendingExternalPayment.update({ where: { id: row.id }, data: { providerRef: order.id } }).catch(() => {});
    return { paypalOrderId: order.id, pendingId: row.id };
  } catch (e) {
    await db.pendingExternalPayment.update({ where: { id: row.id }, data: { status: "FAILED" } }).catch(() => {});
    console.error("[payments] could not create PayPal order", e);
    return { error: "We couldn't start the PayPal payment — please try again." };
  }
}

async function openCoinbase(opts: {
  userId: string;
  kind: string;
  amountCents: number;
  metadata: Record<string, string>;
  name: string;
  description: string;
  redirectPath: string;
  cancelPath: string;
}): Promise<{ error: string } | { hostedUrl: string; pendingId: string }> {
  if (!coinbaseConfigured()) return { error: "Crypto payments aren't set up yet — try another payment method." };
  const row = await db.pendingExternalPayment.create({
    data: {
      provider: "coinbase",
      kind: opts.kind,
      userId: opts.userId,
      amountCents: opts.amountCents,
      currency: "usd",
      metadata: JSON.stringify(opts.metadata),
    },
  });
  try {
    const charge = await createCoinbaseCharge({
      amountCents: opts.amountCents,
      pendingId: row.id,
      name: opts.name,
      description: opts.description,
      redirectUrl: `${appBase()}${opts.redirectPath}`,
      cancelUrl: `${appBase()}${opts.cancelPath}`,
    });
    await db.pendingExternalPayment.update({ where: { id: row.id }, data: { providerRef: charge.code } }).catch(() => {});
    return { hostedUrl: charge.hosted_url, pendingId: row.id };
  } catch (e) {
    await db.pendingExternalPayment.update({ where: { id: row.id }, data: { status: "FAILED" } }).catch(() => {});
    console.error("[payments] could not create Coinbase Commerce charge", e);
    return { error: "We couldn't start the crypto payment — please try again." };
  }
}

/**
 * Capture a PayPal order server-to-server and fulfil it — the PayPal analogue of
 * the Stripe confirm route (app/api/stripe/confirm/route.ts). Called from the
 * wizard's `onApprove` callback; the PayPal webhook is the reliable backstop for
 * the same reason the Stripe webhook is (a closed tab must not be the only thing
 * that could have fulfilled a paid order). Idempotent via `fulfilExternalPayment`'s
 * FulfilledSession claim, so this racing the webhook is safe.
 */
export async function captureExternalPayPalOrder(
  paypalOrderId: string,
  pendingId: string,
): Promise<{ redirect?: string; error?: string }> {
  const user = await requireUser();
  const row = await db.pendingExternalPayment.findUnique({ where: { id: pendingId } });
  if (!row || row.userId !== user.id || row.provider !== "paypal") {
    return { error: "We couldn't find that payment." };
  }

  let captured;
  try {
    captured = await capturePayPalOrder(paypalOrderId);
  } catch (e) {
    console.error("[payments] PayPal capture failed", paypalOrderId, e);
    return { error: "We couldn't confirm that PayPal payment. If you were charged, contact support — your money is safe." };
  }
  if (captured.status !== "COMPLETED") {
    return { error: `PayPal reported this payment as "${captured.status}" — please try again or use another method.` };
  }
  // Defence in depth: the captured amount must match what we asked PayPal to
  // charge. It always will (we set it), but a mismatch here means something is
  // wrong enough that fulfilling on trust would be the bug, not the fix.
  const capturedCents = Math.round(
    Number(captured.purchase_units?.[0]?.payments?.captures?.[0]?.amount?.value ?? "0") * 100,
  );
  if (capturedCents !== row.amountCents) {
    console.error("[payments] PayPal captured amount mismatch", { paypalOrderId, capturedCents, expected: row.amountCents });
    return { error: "That payment didn't match the expected amount. Contact support — nothing has been provisioned." };
  }

  try {
    const result: FulfilResult = await fulfilExternalPayment({
      provider: "paypal",
      externalId: paypalOrderId,
      pendingId,
      base: appBase(),
    });
    return { redirect: result.redirect };
  } catch (e) {
    console.error("[payments] PayPal fulfilment failed", paypalOrderId, e);
    return { error: "Your PayPal payment went through but we couldn't finish setup. Contact support — your money is safe and we've been alerted." };
  }
}

/* ------------------------------------------------------------------ *
 * VPS order — mirrors payAndDeploy's quote/promo/coupon/tax path
 * (lib/actions.ts) up to the point of opening a payment session.
 * ------------------------------------------------------------------ */

async function quoteVpsOrderForExternalPayment(formData: FormData): Promise<
  | { error: string }
  | {
      cardCents: number;
      metadata: Record<string, string>;
      release: () => Promise<void>;
    }
> {
  const user = await requireUser();
  await assertNotImpersonating();
  const unverified = await emailVerificationError(user);
  if (unverified) return { error: unverified };
  const limitErr = await serverLimitError(user.id);
  if (limitErr) return { error: limitErr };

  const intent = intentFromFormData(formData);
  intent.partnerSource = partnerSourceFromCookie(await cookies());

  let quote;
  try {
    quote = await orderQuote(intent);
  } catch (e) {
    if (e instanceof OrderError) return { error: e.message };
    throw e;
  }

  const promoIpHash = hashIp(clientIp(await headers()), process.env.AUTH_SECRET ?? "nxeon") || null;
  if (quote.promoCreditCents > 0 && !(await firstMonthFreeEligible(user.id, promoIpHash))) {
    quote = await orderQuote(intent, { suppressPromo: true });
  }
  const promoCampaign = promoCampaignFromCookie(await cookies());

  const useWallet = formData.get("useWallet") !== "0";
  const taxCtx = await taxContextForUser(user);
  const taxOn = (netCents: number) => Math.round((netCents * taxCtx.ratePercent) / 100);
  const dueWithTax = (netCents: number) => netCents + taxOn(netCents);
  let { cardCents } = walletSplit({ dueCents: dueWithTax(quote.chargeCents), balanceCents: user.balanceCents, useWallet });

  if (cardCents <= 0) {
    return { error: "Your wallet balance already covers this order — deploy it from the Review step without a card." };
  }

  let promoReservationToken: string | null = null;
  let couponReservationToken: string | null = null;
  let checkoutIntent = intent;

  if (quote.promoCreditCents > 0) {
    const reservedUntil = new Date(Date.now() + PAYPAL_HOLD_MS);
    const res = await reserveFirstMonthFree({
      userId: user.id,
      ipHash: promoIpHash,
      serviceType: "VPS",
      campaign: promoCampaign,
      chargedCents: quote.chargeCents,
      reservedUntil,
    });
    if (res.reserved) {
      promoReservationToken = res.token;
    } else {
      quote = await orderQuote(intent, { suppressPromo: true });
      ({ cardCents } = walletSplit({ dueCents: dueWithTax(quote.chargeCents), balanceCents: user.balanceCents, useWallet }));
      if (cardCents <= 0) {
        return { error: "Your wallet balance already covers this order at full price — deploy it from the Review step." };
      }
    }
  }

  if (quote.couponId && quote.couponDiscountCents > 0) {
    const reservedUntil = new Date(Date.now() + PAYPAL_HOLD_MS);
    const res = await reserveOrderCoupon({
      couponId: quote.couponId,
      maxRedemptions: quote.couponMaxRedemptions,
      firstTimeOnly: quote.couponFirstTimeOnly,
      userId: user.id,
      ipHash: promoIpHash,
      amountCents: quote.couponDiscountCents,
      reservedUntil,
    });
    if (res.reserved) {
      couponReservationToken = res.token;
    } else {
      checkoutIntent = { ...intent, couponCode: undefined };
      quote = await orderQuote(checkoutIntent, { suppressPromo: !promoReservationToken });
      ({ cardCents } = walletSplit({ dueCents: dueWithTax(quote.chargeCents), balanceCents: user.balanceCents, useWallet }));
    }
  }

  const release = async () => {
    if (promoReservationToken) await releaseReservation(promoReservationToken).catch(() => {});
    if (couponReservationToken) await releaseOrderCouponReservation(couponReservationToken).catch(() => {});
  };

  const slim: OrderIntent = { ...checkoutIntent, sshPublicKey: undefined, sshKeyName: undefined };
  const sold: OrderPrice = orderPriceOf(quote, { taxCents: taxOn(quote.chargeCents), ratePercent: taxCtx.ratePercent, country: taxCtx.country });
  const metadata: Record<string, string> = {
    nxeonUserId: user.id,
    nxeonOrder: packExternalPaymentMetadata("Order intent", slim),
    nxeonOrderPrice: packExternalPaymentMetadata("Order price", sold),
    nxeonPromoCampaign: promoCampaign ?? "",
    ...(promoReservationToken ? { nxeonPromoReservation: promoReservationToken } : {}),
    ...(couponReservationToken ? { nxeonCouponReservation: couponReservationToken } : {}),
  };

  return { cardCents, metadata, release };
}

export async function createOrderPayPalOrder(formData: FormData): Promise<CreateResult> {
  const user = await requireUser();
  const quoted = await quoteVpsOrderForExternalPayment(formData);
  if ("error" in quoted) return quoted;
  const result = await openPayPal({
    userId: user.id,
    kind: "order",
