// Shared-hosting order pricing — a plain module (no "use server") so it can be
// imported both by lib/actions-hosting.ts (the wallet/card order path) and by
// lib/actions-payment-providers.ts (the PayPal/Coinbase order path) WITHOUT
// either of them re-deriving the formula, and without turning a pure pricing
// helper into a network-callable Server Action export for no reason — see
// test/auth-lockouts.test.ts's "HAZARD" suite, which exists precisely to catch
// exactly that mistake.

import { annualDiscountPct } from "./annual-discount";
import { extraDiskPerGbCents } from "./disk-expand";
import { extraDiskCentsAt } from "./extra-disk";
import { termPriceCents } from "./billing-terms";
import { firstMonthCreditCents } from "./promo-redemption";

/**
 * The money math for a hosting order, in ONE place so the card-split pre-check
 * (`placeHostingOrder`, lib/actions-hosting.ts), the authoritative debit
 * (`orderHostingAccountFor`) and the PayPal/Coinbase order-creation actions
 * (lib/actions-payment-providers.ts) can never diverge on a formula.
 * `fullCharge` is the true total (plan term + storage add-on); `promoCharge` is
 * what a granted first-month-free reduces it to (one PLAN month credited, the
 * add-on never). All the underlying helpers are pure, so call sites only ever
 * differ by the DB reads (annual %, per-GB rate, eligibility) they must each
 * make against the same instant.
 */
export async function hostingChargeCents(
  plan: { priceCents: number },
  term: number,
  extraGB: number,
): Promise<{ annualPct: number; planTermCents: number; extraTermCents: number; fullCharge: number; promoCharge: number }> {
  const annualPct = await annualDiscountPct();
  const perGbCents = await extraDiskPerGbCents();
  const extraTermCents = extraDiskCentsAt(extraGB, perGbCents) * term;
  const planTermCents = termPriceCents(plan.priceCents, term, annualPct);
  const fullCharge = planTermCents + extraTermCents;
  const promoCharge = Math.max(0, planTermCents - firstMonthCreditCents(planTermCents, term)) + extraTermCents;
  return { annualPct, planTermCents, extraTermCents, fullCharge, promoCharge };
}

