import { test } from "node:test";
import assert from "node:assert/strict";
import { readFileSync } from "node:fs";
import { createHmac } from "node:crypto";
import { stripComments } from "./_source-tools.ts";

/**
 * PayPal + Coinbase Commerce — the two new payment rails added alongside Stripe
 * for the embedded Payment step (components/customer/PaymentStep.tsx).
 *
 * WHY THESE TESTS ARE SPLIT THE WAY THEY ARE. `lib/paypal.ts` and
 * `lib/coinbase-commerce.ts` import neither `./db` nor Next.js server-only APIs —
 * both are pure HTTP-client modules — so their webhook-signature functions are
 * exercised for REAL here (real HMAC, real short-circuit-when-unconfigured
 * behaviour), no mocking needed. `app/api/paypal/webhook/route.ts` and
 * `app/api/coinbase/webhook/route.ts` are NOT imported, on purpose: both pull in
 * `lib/fulfil-checkout.ts` -> `./db`, and this suite follows the same rule
 * test/api-http-surface.test.ts documents — "nothing here imports a route
 * module, that would pull in Prisma and open a connection to the production
 * database" — so the routes are asserted against SOURCE instead, the established
 * pattern for exactly this situation (see also test/checkout-fulfilment.test.ts's
 * source tripwires over lib/fulfil-checkout.ts).
 */

function code(relative: string): string {
  return stripComments(readFileSync(new URL(relative, import.meta.url), "utf8"));
}

/* ------------------------------------------------------------------ *
 * Coinbase Commerce webhook signature — real HMAC, no mocking
 * ------------------------------------------------------------------ */

test("Coinbase Commerce: an unconfigured environment rejects every webhook", async () => {
  delete process.env.COINBASE_COMMERCE_WEBHOOK_SECRET;
  const { verifyCoinbaseWebhookSignature, coinbaseConfigured } = await import("../lib/coinbase-commerce.ts");
  assert.equal(coinbaseConfigured(), false);
  assert.equal(await verifyCoinbaseWebhookSignature("{}", "deadbeef"), false);
  assert.equal(await verifyCoinbaseWebhookSignature("{}", null), false);
});

test("Coinbase Commerce: a correctly-signed body verifies", async () => {
  process.env.COINBASE_COMMERCE_WEBHOOK_SECRET = "test-shared-secret";
  const { verifyCoinbaseWebhookSignature } = await import("../lib/coinbase-commerce.ts");
  const body = JSON.stringify({ type: "charge:confirmed", data: { code: "ABC123" } });
  const sig = createHmac("sha256", "test-shared-secret").update(body, "utf8").digest("hex");
  assert.equal(await verifyCoinbaseWebhookSignature(body, sig), true);
  delete process.env.COINBASE_COMMERCE_WEBHOOK_SECRET;
});

test("Coinbase Commerce: a forged or tampered signature is rejected", async () => {
  process.env.COINBASE_COMMERCE_WEBHOOK_SECRET = "test-shared-secret";
  const { verifyCoinbaseWebhookSignature } = await import("../lib/coinbase-commerce.ts");
  const body = JSON.stringify({ type: "charge:confirmed", data: { code: "ABC123" } });
  const realSig = createHmac("sha256", "test-shared-secret").update(body, "utf8").digest("hex");

  // Wrong secret entirely (an attacker guessing).
  const forgedSig = createHmac("sha256", "wrong-secret").update(body, "utf8").digest("hex");
  assert.equal(await verifyCoinbaseWebhookSignature(body, forgedSig), false);

  // Right secret, but the body was tampered with AFTER signing (e.g. amount bumped).
  const tamperedBody = JSON.stringify({ type: "charge:confirmed", data: { code: "ABC999" } });
  assert.equal(await verifyCoinbaseWebhookSignature(tamperedBody, realSig), false);

  // Malformed / non-hex signature must not throw (timingSafeEqual length guard).
  assert.equal(await verifyCoinbaseWebhookSignature(body, "not-hex!!"), false);
  assert.equal(await verifyCoinbaseWebhookSignature(body, ""), false);

  delete process.env.COINBASE_COMMERCE_WEBHOOK_SECRET;
});

/* ------------------------------------------------------------------ *
 * PayPal webhook verification — gated, never a network call when unconfigured
 * ------------------------------------------------------------------ */

test("PayPal: an unconfigured environment rejects every webhook without a network call", async () => {
  delete process.env.PAYPAL_CLIENT_ID;
  delete process.env.PAYPAL_CLIENT_SECRET;
  delete process.env.PAYPAL_WEBHOOK_ID;
  const { verifyPayPalWebhookSignature, paypalConfigured } = await import("../lib/paypal.ts");
  assert.equal(paypalConfigured(), false);
  const headers = new Headers({ "paypal-transmission-id": "x", "paypal-transmission-sig": "y" });
  // Resolves false immediately (the function's own `!paypalConfigured() || !webhookId`
  // short-circuit runs BEFORE any fetch) rather than hanging or throwing on a real
  // network call this test environment has no route to.
  const result = await Promise.race([
    verifyPayPalWebhookSignature(headers, "{}"),
    new Promise((_, reject) => setTimeout(() => reject(new Error("timed out — this must not have reached the network")), 500)),
  ]);
  assert.equal(result, false);
});

test("PayPal: configured but missing PAYPAL_WEBHOOK_ID still rejects without a network call", async () => {
  process.env.PAYPAL_CLIENT_ID = "test-client-id";
  process.env.PAYPAL_CLIENT_SECRET = "test-client-secret";
  delete process.env.PAYPAL_WEBHOOK_ID;
  const { verifyPayPalWebhookSignature, paypalConfigured } = await import("../lib/paypal.ts");
  assert.equal(paypalConfigured(), true); // client id/secret alone ARE "configured"...
  const headers = new Headers();
  // ...but signature verification additionally requires the webhook id (the id of
  // the webhook registered in the PayPal dashboard), so it still refuses rather
  // than calling PayPal with an empty webhook_id.
  const result = await Promise.race([
    verifyPayPalWebhookSignature(headers, "{}"),
    new Promise((_, reject) => setTimeout(() => reject(new Error("timed out — this must not have reached the network")), 500)),
  ]);
  assert.equal(result, false);
  delete process.env.PAYPAL_CLIENT_ID;
  delete process.env.PAYPAL_CLIENT_SECRET;
});

/* ------------------------------------------------------------------ *
 * The webhook ROUTES verify a signature BEFORE ever touching fulfilment
 * ------------------------------------------------------------------ */

const PAYPAL_ROUTE = code("../app/api/paypal/webhook/route.ts");
const COINBASE_ROUTE = code("../app/api/coinbase/webhook/route.ts");

test("the PayPal webhook route verifies the signature before fulfilling anything", () => {
  assert.match(PAYPAL_ROUTE, /verifyPayPalWebhookSignature\(/, "must call the real verifier");
  const verifyAt = PAYPAL_ROUTE.indexOf("verifyPayPalWebhookSignature(");
  const fulfilAt = PAYPAL_ROUTE.indexOf("fulfilExternalPayment(");
  assert.ok(verifyAt >= 0 && fulfilAt >= 0, "both calls must be present");
  assert.ok(verifyAt < fulfilAt, "signature verification must happen BEFORE fulfilment is ever attempted");
  // An unverified webhook must 400, not fall through and process the event anyway.
  assert.match(PAYPAL_ROUTE, /if\s*\(!verified\)\s*\{\s*return NextResponse\.json\([^)]*status:\s*400/s);
});

test("the Coinbase Commerce webhook route verifies the signature before fulfilling anything", () => {
  assert.match(COINBASE_ROUTE, /verifyCoinbaseWebhookSignature\(/, "must call the real verifier");
  const verifyAt = COINBASE_ROUTE.indexOf("verifyCoinbaseWebhookSignature(");
  const fulfilAt = COINBASE_ROUTE.indexOf("fulfilExternalPayment(");
  assert.ok(verifyAt >= 0 && fulfilAt >= 0, "both calls must be present");
  assert.ok(verifyAt < fulfilAt, "signature verification must happen BEFORE fulfilment is ever attempted");
  assert.match(COINBASE_ROUTE, /if\s*\(!verified\)\s*\{\s*return NextResponse\.json\([^)]*status:\s*400/s);
});

test("both webhook routes read the RAW body for signature verification, never req.json()", () => {
  // Parsing JSON first and re-stringifying (or verifying against the parsed
  // object) changes whitespace/key order and breaks HMAC/signature verification
  // silently — the exact mistake the Stripe webhook's own comment warns about.
  for (const [name, src] of [["paypal", PAYPAL_ROUTE], ["coinbase", COINBASE_ROUTE]] as const) {
    assert.match(src, /const raw = await req\.text\(\)/, `${name} webhook must read the raw body`);
