/* ------------------------------------------------------------------ *
 * Fulfilment-path unification: PayPal, Coinbase and Stripe all reach the
 * SAME dispatch function — this is the seam the whole build exists to prove.
 * ------------------------------------------------------------------ */

const FULFIL = code("../lib/fulfil-checkout.ts");

test("fulfilCheckoutSession (Stripe) and fulfilExternalPayment (PayPal/Coinbase) call the SAME dispatch", () => {
  assert.match(FULFIL, /async function runFulfilment\(/, "the one dispatch function must exist");
  // Exactly one definition — never a second copy of the claim/settle/provision logic.
  assert.equal((FULFIL.match(/(?:async )?function runFulfilment\(/g) ?? []).length, 1, "runFulfilment must be defined exactly once");
  // Exactly two callers: the Stripe wrapper and the external-payment wrapper.
  assert.equal((FULFIL.match(/await runFulfilment\(/g) ?? []).length, 2, "runFulfilment must have exactly two callers");

  const stripeFn = FULFIL.slice(FULFIL.indexOf("export async function fulfilCheckoutSession"), FULFIL.indexOf("async function runFulfilment("));
  assert.match(stripeFn, /return runFulfilment\(session, purpose, base, "stripe"\)/, "Stripe's wrapper must dispatch through runFulfilment");

  const externalFn = FULFIL.slice(FULFIL.indexOf("export async function fulfilExternalPayment"));
  assert.match(externalFn, /await runFulfilment\(synthetic, purpose, input\.base \?\? "", input\.provider\)/, "the external-payment wrapper must dispatch through the SAME runFulfilment");
});

test("fulfilExternalPayment builds its synthetic session from the SAME classifyCheckoutSession Stripe uses", () => {
  const externalFn = FULFIL.slice(FULFIL.indexOf("export async function fulfilExternalPayment"));
  assert.match(externalFn, /classifyCheckoutSession\(synthetic\)/, "must classify through the one shared classifier, not a second copy");
});

test("PayPal/Coinbase never record a card for renewal — that step is Stripe-only", () => {
  // saveCardFromPaymentSession needs a real Stripe PaymentIntent + customer; there
  // is none for a PayPal/Coinbase payment. Every call site must be gated.
  const saveCardCalls = [...FULFIL.matchAll(/(if \(provider === "stripe"[^{]*\{\s*)?\s*(try \{\s*)?await saveCardFromPaymentSession\(/g)];
  assert.ok(saveCardCalls.length >= 7, "expected at least 7 saveCardFromPaymentSession call sites (unchanged from before this build)");
  // Structural guarantee: every occurrence of the call is preceded somewhere above
  // it (within a small window) by a `provider === "stripe"` check. We assert this
  // the same way the codebase's other tripwires do: no unconditional call exists
  // outside an `if (provider === "stripe")` block, by checking each call site's
  // nearest preceding 200 characters contains the guard.
  let idx = FULFIL.indexOf("await saveCardFromPaymentSession(");
  let guardedCount = 0;
  let totalCount = 0;
  while (idx !== -1) {
    totalCount++;
    const windowStart = Math.max(0, idx - 220);
    if (FULFIL.slice(windowStart, idx).includes('provider === "stripe"')) guardedCount++;
    idx = FULFIL.indexOf("await saveCardFromPaymentSession(", idx + 1);
  }
  assert.equal(guardedCount, totalCount, "every saveCardFromPaymentSession call must be gated on provider === \"stripe\"");
});

test("crediting a PayPal/Coinbase payment never labels it a \"Stripe payment\" in the ledger", () => {
  const creditExternalFn = FULFIL.slice(
