  /** What is actually charged to the chosen payment method today. */
  totalDueCents: number;
  onEdit: () => void;
};

type StripeSessionState =
  | { status: "idle" }
  | { status: "loading" }
  | { status: "ready"; clientSecret: string; publishableKey: string }
  | { status: "error"; message: string };

export type PaymentStepProps = {
  summary: PaymentStepSummary;
  email: string;
  onBack: () => void;

  /** Stripe: card / Google Pay / Apple Pay. */
  stripe: StripeSessionState;
  /** Ask the parent to (re)create the Stripe Custom Checkout session. Called
   *  automatically on mount/price-change AND from the "try again" control. */
  onRequestStripeSession: () => void;

  /** PayPal — omitted from the method list entirely when not configured. */
  paypal: { ready: boolean; clientId: string } | null;
  createPayPalOrder: () => Promise<{ paypalOrderId: string; pendingId: string } | { error: string }>;
  capturePayPalOrder: (paypalOrderId: string, pendingId: string) => Promise<{ redirect?: string; error?: string }>;

  /** Coinbase Commerce — omitted entirely when not configured. */
  coinbaseReady: boolean;
  createCoinbaseCharge: () => Promise<{ hostedUrl: string; pendingId: string } | { error: string }>;

  /** Only populate when a product has a REAL, published, honoured guarantee.
   *  See WizardTrustBar.tsx / PaymentTrustBar.tsx's HONESTY notes — there is
   *  none today, so every current caller omits this and the callout is hidden
   *  rather than showing a fabricated claim. */
  moneyBackDays?: number;
};

type Method = "card" | "google_pay" | "apple_pay" | "paypal" | "coinbase";

const money = (cents: number) => `$${(cents / 100).toFixed(2)}`;

