/* ------------------------------------------------------------------ *
 * Card + Google Pay + Apple Pay — all children of ONE CheckoutProvider
 * ------------------------------------------------------------------ */

const stripeCache = new Map<string, Promise<StripeJs | null>>();
function stripeFor(pk: string): Promise<StripeJs | null> {
  let p = stripeCache.get(pk);
  if (!p) {
    p = loadStripe(pk);
    stripeCache.set(pk, p);
  }
  return p;
}

/** Shared appearance so the Payment Element reads as part of THIS page, not a
 *  visiting Stripe widget — dark surfaces matching the wizard's card chrome. */
const STRIPE_APPEARANCE = {
  theme: "night" as const,
  variables: {
    colorPrimary: "#7c5cff",
    colorBackground: "#0b0f1f",
    colorText: "#e2e8f0",
    colorDanger: "#f87171",
    fontFamily: "inherit",
    borderRadius: "10px",
    spacingUnit: "4px",
  },
  rules: {
    ".Input": { border: "1px solid rgba(255,255,255,0.09)", boxShadow: "none" },
    ".Input:focus": { border: "1px solid rgba(124,92,255,0.6)", boxShadow: "0 0 0 1px rgba(124,92,255,0.4)" },
    ".Label": { color: "#94a3b8" },
  },
};

/** Renders inside `<CheckoutProvider>` — the only place `useCheckout()` is valid. */
function CardAndWalletsBlock({
  selected,
  onSelectCard,
  onSelectGooglePay,
  onSelectApplePay,
  saveCard,
  onToggleSaveCard,
  totalDueCents,
}: {
  selected: Method;
  onSelectCard: () => void;
  onSelectGooglePay: () => void;
  onSelectApplePay: () => void;
  saveCard: boolean;
  onToggleSaveCard: (v: boolean) => void;
  totalDueCents: number;
}) {
  const checkout = useCheckout();
  const [confirming, setConfirming] = useState(false);
  const [error, setError] = useState<string | null>(null);
  const [name, setName] = useState("");
  const [googlePayAvailable, setGooglePayAvailable] = useState(false);
  const [applePayAvailable, setApplePayAvailable] = useState(false);

  async function payWithCard() {
    setError(null);
    setConfirming(true);
    try {
      const result = await checkout.confirm({ savePaymentMethod: saveCard });
      if (result.type === "error") setError(result.error.message ?? "Your card was declined. Please try another payment method.");
      // On success Stripe navigates the browser to the session's return_url
      // (/api/stripe/confirm) — the SAME route that fulfils every other Stripe
      // payment on this platform. Nothing else to do here.
    } catch {
      setError("Something went wrong confirming your payment. Please try again.");
    } finally {
      setConfirming(false);
    }
  }

  return (
    <>
      <MethodRow
        id="card"
        selected={selected === "card"}
        onSelect={onSelectCard}
        icon={<CardIcon />}
        title="Credit / Debit Card"
        subtitle="Visa, Mastercard, American Express and more"
      >
        <div className="space-y-4">
          <div>
            <label className="mb-1.5 flex items-center gap-1.5 text-xs font-medium text-slate-400">
              <LockIcon /> Card details
            </label>
            <div className="rounded-lg border border-white/[0.08] bg-white/[0.02] p-3">
              <PaymentElement
                options={{
                  layout: "tabs",
                  fields: { billingDetails: { name: "never" } },
                  paymentMethodOrder: ["card"],
                }}
              />
            </div>
          </div>
          <div>
            <label className="mb-1.5 block text-xs font-medium text-slate-400">Cardholder name</label>
            <input
              type="text"
              value={name}
              onChange={(e) => setName(e.target.value)}
              placeholder="Name on card"
              className="w-full rounded-lg border border-white/[0.08] bg-white/[0.02] px-3 py-2 text-sm text-slate-200 placeholder:text-slate-600 focus:border-brand-400/50 focus:outline-none"
            />
          </div>
          <label className="flex items-start gap-2.5 rounded-lg border border-white/[0.06] bg-white/[0.02] px-3 py-2.5">
            <input type="checkbox" checked={saveCard} disabled className="mt-0.5 h-3.5 w-3.5 accent-brand-500" onChange={(e) => onToggleSaveCard(e.target.checked)} />
            <span className="text-xs text-slate-400">
              <span className="font-medium text-slate-300">Save card for faster checkout</span>
              <br />
              Nxeon plans renew automatically, so your card is always saved securely with Stripe for your next billing cycle — this isn&apos;t optional for a subscription product, which is why the box is checked.
            </span>
          </label>
          {error && <p className="rounded-lg border border-red-500/25 bg-red-500/10 px-3 py-2 text-xs text-red-300">{error}</p>}
          <button
            type="button"
            onClick={payWithCard}
            disabled={confirming || !checkout.canConfirm}
            className="btn-primary flex w-full items-center justify-center gap-2 py-3 text-sm font-semibold"
          >
            <LockIcon className="h-4 w-4" />
            {confirming ? "Processing…" : `Pay Securely ${money(totalDueCents)}`}
          </button>
        </div>
      </MethodRow>

      {/* Two independent Express Checkout Element instances, each filtered to
          ONE wallet, so they render as the mockup's separate Google Pay / Apple
          Pay rows rather than one combined "express" blob. Each hides itself
          entirely (via onReady's availablePaymentMethods) when that wallet
          genuinely isn't available on this browser/device/card. */}
      <MethodRow
        id="google_pay"
        selected={selected === "google_pay"}
        onSelect={onSelectGooglePay}
        icon={<GoogleGIcon />}
        title="Google Pay"
        subtitle="Pay with Google Pay"
        badge={{ text: "Fast & Secure", cls: "bg-emerald-500/15 text-emerald-300" }}
        disabled={!googlePayAvailable}
      >
        <div className={selected === "google_pay" ? "" : "hidden"}>
          <ExpressCheckoutElement
            options={{ paymentMethods: { googlePay: "always", applePay: "never", link: "never", paypal: "never", amazonPay: "never" } }}
            onReady={(e) => setGooglePayAvailable(!!e.availablePaymentMethods?.googlePay)}
            onConfirm={async (event) => {
              setError(null);
              const result = await checkout.confirm({ expressCheckoutConfirmEvent: event });
              if (result.type === "error") setError(result.error.message ?? "Google Pay payment failed.");
            }}
          />
        </div>
      </MethodRow>
      <MethodRow
        id="apple_pay"
        selected={selected === "apple_pay"}
        onSelect={onSelectApplePay}
        icon={<AppleIcon />}
        title="Apple Pay"
        subtitle="Pay with Apple Pay"
        badge={{ text: "Fast & Secure", cls: "bg-emerald-500/15 text-emerald-300" }}
        disabled={!applePayAvailable}
      >
        <div className={selected === "apple_pay" ? "" : "hidden"}>
          <ExpressCheckoutElement
            options={{ paymentMethods: { applePay: "always", googlePay: "never", link: "never", paypal: "never", amazonPay: "never" } }}
            onReady={(e) => setApplePayAvailable(!!e.availablePaymentMethods?.applePay)}
            onConfirm={async (event) => {
              setError(null);
              const result = await checkout.confirm({ expressCheckoutConfirmEvent: event });
              if (result.type === "error") setError(result.error.message ?? "Apple Pay payment failed.");
            }}
          />
        </div>
      </MethodRow>
    </>
  );
}

/* ------------------------------------------------------------------ *
 * Main component
 * ------------------------------------------------------------------ */

export function PaymentStep(props: PaymentStepProps) {
  const { summary, stripe, onRequestStripeSession, paypal, coinbaseReady } = props;
  const [method, setMethod] = useState<Method>("card");
  const [saveCard, setSaveCard] = useState(true);
  const [agreedToTerms, setAgreedToTerms] = useState(false);
  const [email, setEmail] = useState(props.email);
  const [payPalPendingId, setPayPalPendingId] = useState<string | null>(null);
  const [payPalError, setPayPalError] = useState<string | null>(null);
  const [coinbaseBusy, setCoinbaseBusy] = useState(false);
  const [coinbaseError, setCoinbaseError] = useState<string | null>(null);
  const requestedRef = useRef(false);

  // Ask for a Stripe session as soon as this step is visible, so Card/Google
  // Pay/Apple Pay are ready to accept input immediately (matching the mockup)
  // instead of only appearing after a click. One request per mount; the wizard
  // re-invokes this itself (via a changed `key` or a fresh call) if the price
  // changes (coupon applied, wallet toggle, etc).
  useEffect(() => {
    if (!requestedRef.current && stripe.status === "idle") {
      requestedRef.current = true;
      onRequestStripeSession();
    }
  }, [stripe.status, onRequestStripeSession]);

  const stripePromise = useMemo(
    () => (stripe.status === "ready" ? stripeFor(stripe.publishableKey) : null),
    [stripe.status, stripe.status === "ready" ? stripe.publishableKey : null],
  );

  async function handlePayPalApprove(orderID: string) {
    if (!payPalPendingId) return;
    const res = await props.capturePayPalOrder(orderID, payPalPendingId);
    if (res.error) {
      setPayPalError(res.error);
      return;
    }
    if (res.redirect) window.location.href = res.redirect;
  }

  async function handleCoinbase() {
    setCoinbaseError(null);
    setCoinbaseBusy(true);
    try {
      const res = await props.createCoinbaseCharge();
      if ("error" in res) {
        setCoinbaseError(res.error);
        return;
      }
      window.location.href = res.hostedUrl;
    } finally {
      setCoinbaseBusy(false);
    }
  }

  const payDisabled = !agreedToTerms;

  return (
    <div className="grid gap-6 lg:grid-cols-[1fr_380px]">
      {/* ── Left column: Payment ─────────────────────────────────────────── */}
      <div>
        <div className="flex items-center gap-2.5">
          <span className="flex h-9 w-9 items-center justify-center rounded-xl bg-brand-500/15 text-brand-300">
            <ShieldIcon />
          </span>
          <div>
            <h2 className="text-lg font-semibold text-slate-100">Payment</h2>
            <p className="text-xs text-slate-500">All transactions are secure and encrypted</p>
          </div>
        </div>

        <fieldset disabled={payDisabled} className={payDisabled ? "opacity-90" : ""}>
          <p className="mb-3 mt-6 text-sm font-medium text-slate-300">1. Choose a payment method</p>
          <div className="space-y-3">
            {stripe.status === "error" ? (
              <div className="rounded-xl border border-amber-500/25 bg-amber-500/10 px-4 py-3 text-sm text-amber-300">
                Card payments aren&apos;t available right now ({stripe.message}).{" "}
                {paypal?.ready || coinbaseReady ? "Try PayPal or crypto below, or " : ""}
                <button type="button" className="underline" onClick={onRequestStripeSession}>
                  try again
                </button>
                .
              </div>
            ) : stripe.status === "ready" && stripePromise ? (
              <CheckoutProvider
                stripe={stripePromise}
                options={{ clientSecret: stripe.clientSecret, elementsOptions: { appearance: STRIPE_APPEARANCE } }}
              >
                <CardAndWalletsBlock
                  selected={method}
                  onSelectCard={() => setMethod("card")}
                  onSelectGooglePay={() => setMethod("google_pay")}
                  onSelectApplePay={() => setMethod("apple_pay")}
                  saveCard={saveCard}
                  onToggleSaveCard={setSaveCard}
                  totalDueCents={summary.totalDueCents}
                />
              </CheckoutProvider>
            ) : (
              <div className="rounded-xl border border-white/[0.07] bg-white/[0.02] px-4 py-6 text-center text-sm text-slate-500">
                <span className="inline-block h-4 w-4 animate-spin rounded-full border-2 border-slate-600 border-t-brand-400 align-[-3px]" />{" "}
                Preparing secure payment form…
              </div>
            )}

            {paypal?.ready && (
              <PayPalScriptProvider options={{ clientId: paypal.clientId, currency: "USD", intent: "capture" }}>
                <MethodRow
                  id="paypal"
                  selected={method === "paypal"}
                  onSelect={() => setMethod("paypal")}
                  icon={<PayPalGlyph />}
                  title="PayPal"
                  subtitle="Pay with PayPal"
                  badge={{ text: "Secure", cls: "bg-blue-500/15 text-blue-300" }}
                >
                  <div className="space-y-2">
                    {payPalError && <p className="rounded-lg border border-red-500/25 bg-red-500/10 px-3 py-2 text-xs text-red-300">{payPalError}</p>}
                    <PayPalButtons
                      fundingSource={FUNDING.PAYPAL}
                      style={{ layout: "horizontal", color: "gold", shape: "pill", height: 45, tagline: false }}
                      disabled={payDisabled}
                      createOrder={async () => {
                        setPayPalError(null);
                        const res = await props.createPayPalOrder();
                        if ("error" in res) {
                          setPayPalError(res.error);
                          throw new Error(res.error);
                        }
                        setPayPalPendingId(res.pendingId);
                        return res.paypalOrderId;
                      }}
                      onApprove={async (data) => {
                        await handlePayPalApprove(data.orderID);
                      }}
                      onError={() => setPayPalError("PayPal couldn't complete this payment. Please try again.")}
                    />
                  </div>
                </MethodRow>
              </PayPalScriptProvider>
            )}

            {coinbaseReady && (
              <MethodRow
                id="coinbase"
                selected={method === "coinbase"}
                onSelect={() => setMethod("coinbase")}
                icon={<CryptoIcon />}
                title="Cryptocurrency"
                subtitle="Pay with Bitcoin, Ethereum, USDC and more via Coinbase Commerce"
              >
                <div className="space-y-3">
                  <div className="flex items-center gap-2 text-slate-400">
                    <CoinGlyph label="₿" />
                    <CoinGlyph label="Ξ" />
                    <CoinGlyph label="$" />
                    <span className="text-xs">Bitcoin · Ethereum · USDC and more</span>
                  </div>
                  <p className="text-xs text-slate-500">
                    You&apos;ll be redirected to Coinbase Commerce to complete payment, then brought back here automatically.
                  </p>
                  {coinbaseError && <p className="rounded-lg border border-red-500/25 bg-red-500/10 px-3 py-2 text-xs text-red-300">{coinbaseError}</p>}
                  <button
                    type="button"
                    onClick={handleCoinbase}
                    disabled={payDisabled || coinbaseBusy}
                    className="btn-primary flex w-full items-center justify-center gap-2 py-3 text-sm font-semibold"
                  >
                    {coinbaseBusy ? "Redirecting…" : `Continue to Coinbase — ${money(summary.totalDueCents)}`}
                  </button>
                </div>
              </MethodRow>
            )}
          </div>

          <p className="mb-3 mt-8 text-sm font-medium text-slate-300">2. Billing information</p>
          <div className="space-y-3">
            <div>
              <label className="mb-1.5 block text-xs font-medium text-slate-400">Email</label>
              <input
                type="email"
                value={email}
                onChange={(e) => setEmail(e.target.value)}
                className="w-full rounded-lg border border-white/[0.08] bg-white/[0.02] px-3 py-2 text-sm text-slate-200 focus:border-brand-400/50 focus:outline-none"
              />
              <p className="mt-1 text-[11px] text-slate-500">Your invoice will be sent to this email.</p>
            </div>
          </div>
        </fieldset>

        <label className="mt-4 flex items-start gap-2.5">
          <input
            type="checkbox"
            checked={agreedToTerms}
            onChange={(e) => setAgreedToTerms(e.target.checked)}
            className="mt-0.5 h-4 w-4 accent-brand-500"
          />
          <span className="text-xs text-slate-400">
            I agree to Nxeon&apos;s{" "}
            <a href="/legal/terms" target="_blank" rel="noreferrer" className="text-brand-300 underline">
              Terms of Service
            </a>{" "}
            and{" "}
            <a href="/legal/privacy" target="_blank" rel="noreferrer" className="text-brand-300 underline">
              Privacy Policy
            </a>
            .
          </span>
        </label>

        <PaymentTrustBar className="mt-6" />

        <div className="mt-6 flex items-center justify-between">
          <button type="button" className="btn-ghost" onClick={props.onBack}>
            ← Back
          </button>
