// Ask for a Stripe session as soon as this step is visible, so Card/Google
// Pay/Apple Pay are ready to accept input immediately (matching the mockup)
// instead of only appearing after a click. `stripe.status` is entirely
// PARENT-controlled: the wizard flips it away from "idle" the instant it acts
// on this call, and flips it BACK to "idle" itself if the price changes after
// a session was already created (a coupon applied, the wallet toggle changed)
// — so this effect re-requests a fresh session exactly when the parent decides
// the old one is stale, with no local "only once" state of its own to fight it.
useEffect(() => {
  if (stripe.status === "idle") onRequestStripeSession();
}, [stripe.status, onRequestStripeSession]);

